mapper.select:
select *
from goods
where delete_status = 0
order by
    /* 待审核优先，其次按最新时间/ID倒序 */
    case when audit_status = 0 then 0 else 1 end,
    /* 若表含 add_time 列则优先按发布时间倒序，否则按 id 倒序 */
    /* 兼容：多数 MySQL 会允许同时存在，次序上 id 兜底 */
    add_time desc,
    id desc

select * from goods
status = 1 and audit_status = 1 and delete_status = 0
and brand_id = #{brandId}
and price >= #{minPrice}
and price <= #{maxPrice}
and condition_level = #{conditionLevel}
order by
price asc
price desc
view_count desc
view_count desc
add_time desc

mapper.update:
update goods
set stock = stock - #{count}
where id = #{id}
  and stock >= #{count}

update goods
set stock = stock + #{count}
where id = #{id}

update goods
set view_count = ifnull(view_count, 0) + 1
where id = #{id}
